null, "host_organization_lineage": [], "host_organization_lineage_names": [], "type": "repository"}, "license": "cc-by", "license_id": "https://openalex.org/licenses/cc-by", "version": "submittedVersion", "is_accepted": false, "is_published": false, "raw_source_name": null, "raw_type": "doctoral thesis"}, "abstract": "The integration of Artificial Intelligence (AI) into modern weaponry has brought significant changes to warfare tactics and the application of military force. The operation of Autonomous Weapon Systems (AWS), which select targets without human involvement, challenges the existing legal frameworks, humanitarian standards, and ethical principles. This thesis examines the capacity of international law to regulate AI-based conflict operations while safeguarding human life, dignity, and humanitarian values. The research adopts an interdisciplinary perspective to explore how International Humanitarian Law, International Human Rights Law, ethics, and technology interact when governing AWS operations. It demonstrates that the deployment of AWS under current technological conditions challenges fundamental ethical rules, creating problems for regulatory systems by undermining essential principles of distinction, proportionality, and the right to life. The research analyzes legal precedents, state practices, and UN expert deliberations to assess the limitations of existing frameworks. Beyond the legal evaluation, it also examines the moral legitimacy of AWS by applying ethical theory to determine whether machine decision systems require moral reasoning and accountability, and whether they can or should be integrated into autonomous decision-making systems. The study shows that AI technology enables more effective surveillance and risk management, yet meaningful human oversight must remain central to any legally and ethically acceptable military operations. It shows that there is an urgent need to create a new regulatory framework that protects human rights through ethical standards, transparency, and technological understanding. Ultimately, the thesis concludes that AWS regulation must be grounded in International Humanitarian Law and International Human Rights Law, operating through a system that protects human rights, maintains transparency and accountability, and preserves human life. It develops policy recommendations for international institutions and states to promote responsible innovation and peace amid the growing use of autonomous warfare."}]", "excerpt_truncated": true, "source_sha256": "7e4821791e4eb205e5f4b402cf5753e2c6a4aaef2b205ca820db4ef4cb02add6", "verification_required": true, "topic_domain": "obedience_limits", "evidence_role": "discovery", "host_tier": "discovery", "source_identity": null, "persistent_identifiers": ["doi:10.18653/v1/2025.findings-acl.67", "openalex:W4412888948", "openalex:W7162895030"], "source_candidates": ["https://doi.org/10.18653/v1/2025.findings-acl.67", "https://aclanthology.org/2025.findings-acl.67.pdf", "https://academicworks.cuny.edu/context/gc_etds/article/7858/viewcontent/Cromie_final.pdf"], "source_candidate_identities": {}}

